package com.civicfix.model;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(unique=true,nullable=false) private String email; @Column(nullable=false) private String passwordHash; @Enumerated(EnumType.STRING) private Role role=Role.CITIZEN; private String department; private Instant createdAt=Instant.now(); public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} }
